class enigma:
    def __iter__(self):
        self.x = 128
        return self
    def __next__(self):
        y = self.x
        z = lambda a : a - int(a/2)
        self.x = z(self.x)
        return y

coisa = enigma()
xpto = iter(coisa)
for k in range(5):
    print(next(xpto))

