insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,36,'Prova objetiva','A Internet das coisas (IoT) aumenta a quantidade e a complexidade dos dados por meio de novas formas e novas fontes de informações, influenciando diretamente em uma ou mais das características do big data, a exemplo de volume, velocidade e variedade.','Com referência à transformação digital, julgue o próximo item.',null,'["Certo", "Errado"]'::jsonb,'A','Gabarito definitivo da banca: Certo' from public.exams where slug='prf-2021-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,37,'Prova objetiva','Ransomware é um programa malicioso de computador que se propaga por meio da inserção de cópias de si mesmo em arquivos criptografados.','A respeito de segurança e de cloud computing, julgue os itens subsequentes.',null,'["Certo", "Errado"]'::jsonb,'B','Gabarito definitivo da banca: Errado' from public.exams where slug='prf-2021-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
