insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,51,'Prova objetiva','A duplicação dos principais eixos rodoviários, a restruturação do modelo de investimento e de exploração das ferrovias e a expansão e o aumento da capacidade da malha ferroviária são considerados condições para o desenvolvimento das regiões brasileiras no que diz respeito às redes de transporte.','No que se refere à rede de transportes no Brasil, julgue os itens que se seguem.',null,'["Certo", "Errado"]'::jsonb,'A','Gabarito definitivo da banca: Certo' from public.exams where slug='prf-2021-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
