insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,65,'Prova objetiva','Como os reboques e os semirreboques são identificados somente por placa de identificação veicular (PIV) traseira, caso seja necessário, veículos equipados com engates para reboques ou com carroceria intercambiável deverão obrigatoriamente usar uma segunda PIV traseira.','Considerando as resoluções do Conselho Nacional de Trânsito (CONTRAN) e suas alterações, julgue os itens que se seguem.',null,'["Certo", "Errado"]'::jsonb,'A','Gabarito definitivo da banca: Certo' from public.exams where slug='prf-2021-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
