insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,80,'Prova objetiva','O slogan da campanha educativa de trânsito de 2021, a qual deve ser veiculada, obrigatoriamente, nos meios de comunicação social, em toda peça publicitária de produtos automobilísticos, é: “No trânsito, sua responsabilidade salva vidas”.','No que concerne a campanha educativa de trânsito e fiscalização de peso dos veículos por balança rodoviária, julgue os itens que se seguem.',null,'["Certo", "Errado"]'::jsonb,'A','Gabarito definitivo da banca: Certo' from public.exams where slug='prf-2021-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
