insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,82,'Prova objetiva','Em rodovias federais, na fiscalização de peso dos veículos por balança rodoviária, é admitida a tolerância de 12,5 % sobre os limites de peso regulamentares por eixo de veículos transmitidos à superfície das vias públicas.','No que concerne a campanha educativa de trânsito e fiscalização de peso dos veículos por balança rodoviária, julgue os itens que se seguem.',null,'["Certo", "Errado"]'::jsonb,'B','Gabarito definitivo da banca: Errado' from public.exams where slug='prf-2021-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
