insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,116,'Prova objetiva','A mera intuição de que esteja havendo tráfico de drogas em uma casa não configura justa causa para autorizar o ingresso sem mandado judicial ou sem o consentimento do morador, exceto em caso de flagrante delito.','À luz da Constituição Federal de 1988 (CF), do Pacto de São José da Costa Rica e do entendimento do Supremo Tribunal Federal, julgue os itens que se seguem, relativos aos direitos humanos.',null,'["Certo", "Errado"]'::jsonb,'A','Gabarito definitivo da banca: Certo' from public.exams where slug='prf-2021-ingles' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
