insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,85,'Prova objetiva','Para a amarração da carga, devem ser utilizadas cintas têxteis, correntes ou cabos de aço, com resistência total à ruptura por tração de, no mínimo, 1,50 vez o peso da carga. BLOCO III','Acerca dos requisitos mínimos de segurança para o transporte de cargas em veículos, julgue os próximos itens.',null,'["Certo", "Errado"]'::jsonb,'B','Gabarito definitivo da banca: Errado' from public.exams where slug='prf-2021-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,86,'Prova objetiva','A impetração de mandado de segurança configura controle judicial de mérito administrativo.','Determinado órgão público firmou contrato administrativo com uma empresa de reconhecida especialização no mercado, para a prestação de serviços de treinamento de pessoal de natureza singular aos seus servidores. Durante a execução do contrato, a empresa descumpriu uma das cláusulas contratuais. A administração pública, então, aplicou multa por inexecução parcial do acordado. Insatisfeita, a empresa impetrou mandado de segurança no Poder Judiciário em face do ato administrativo que aplicara a penalidade sem prévia oitiva. Considerando essa situação hipotética, julgue os itens que se seguem.',null,'["Certo", "Errado"]'::jsonb,'B','Gabarito definitivo da banca: Errado' from public.exams where slug='prf-2021-espanhol' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
