insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Prova objetiva','O estrangeiro condenado por autoridades estrangeiras pela prática de crime político poderá ser extraditado do Brasil se houver reciprocidade do país solicitante.','Julgue os itens subsequentes, relativos aos direitos e garantias fundamentais previstos na CF.','{"support": ["/provas/nacionais/apoio/dprf13_001_01/3-304-49.png"]}','["Certo", "Errado"]'::jsonb,'B','Gabarito definitivo da banca: Errado' from public.exams where slug='prf-2013' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,33,'Prova objetiva','Aos que comprovem insuficiência de recursos é assegurada a gratuidade na prestação de assistência jurídica integral pelo Estado.','Julgue os itens subsequentes, relativos aos direitos e garantias fundamentais previstos na CF.','{"support": ["/provas/nacionais/apoio/dprf13_001_01/3-304-49.png"]}','["Certo", "Errado"]'::jsonb,'A','Gabarito definitivo da banca: Certo' from public.exams where slug='prf-2013' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
