insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,41,'Prova objetiva','Considere que os usuários de determinado serviço público tenham formado longas filas à espera de atendimento por determinado servidor que, embora responsável pelo setor, não viabilizou o atendimento. Nessa situação, segundo dispõe a legislação de regência, a atitude do servidor caracteriza conduta contrária à ética e ato de desumanidade, mas não grave dano moral aos usuários do serviço.','A respeito da ética no serviço público, julgue os itens subsequentes.',null,'["Certo", "Errado"]'::jsonb,'B','Gabarito definitivo da banca: Errado' from public.exams where slug='prf-2013' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,42,'Prova objetiva','O elemento ético deve estar presente na conduta de todo servidor público, que deve ser capaz de discernir o que é honesto e desonesto no exercício de sua função.','A respeito da ética no serviço público, julgue os itens subsequentes.',null,'["Certo", "Errado"]'::jsonb,'A','Gabarito definitivo da banca: Certo' from public.exams where slug='prf-2013' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
insert into public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Prova objetiva','Os registros que consistiram em objeto de apuração e aplicação de penalidade referentes à conduta ética do servidor devem ficar arquivados junto à comissão de ética e não podem ser fornecidos a outras unidades do órgão a que se encontre vinculado o servidor.','No que se refere aos deveres do servidor público, previstos no Código de Ética Profissional do Servidor Público Civil do Poder Executivo Federal, julgue os próximos itens.',null,'["Certo", "Errado"]'::jsonb,'B','Gabarito definitivo da banca: Errado' from public.exams where slug='prf-2013' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
